  function addRoadLog(text,type='relief'){const line=document.createElement('div');line.className=`log-line ${type}`;line.textContent=text;$('logFeed').prepend(line);while($('logFeed').children.length>4)$('logFeed').lastElementChild.remove()}
   function emitRoadFlavor(){const living=crew.filter(member=>member.health>0),hasTrait=trait=>living.some(member=>member.negativeTrait===trait);let text,type,roll=Math.random();if(roll<.28){const reliefs=['A pale strip of sunlight reaches the dashboard. For a moment, the road feels less endless.','The engine settles into a steady rhythm; everyone unclenches their jaw.','A clean patch of road. No alarms, no voices on the radio.','Someone shares a terrible joke. It gets a real laugh anyway.'];text=pick(reliefs);type='relief';if(Math.random()<.35)morale=Math.min(100,morale+1)}else if(roll<.56){const frictions=[];if(hasTrait('Paranoid'))frictions.push('Paranoid eyes keep searching the mirrors; the crew grows tense.');if(hasTrait('Glutton'))frictions.push('Glutton’s snack stash is discovered. The argument leaves everyone irritated.');if(hasTrait('Reckless'))frictions.push('Reckless driving rattles the crew; everyone loses a little nerve.');if(hasTrait('Sickly'))frictions.push('Sickly coughs echo through the van; the crew worries about getting run down.');if(!frictions.length)frictions.push('A short argument over the radio leaves everyone on edge.');text=pick(frictions);type='tension';if(Math.random()<.55){if(Math.random()<.5){morale=Math.max(0,morale-1);text+=' −1 MORALE.'}else{const dip=1+Math.floor(Math.random()*2);food=Math.max(0,food-dip);text+=` −${dip} RATIONS.`}}}else{const moments=['A cracked music player coughs up half a song.','Jun spots birds circling a distant water tower.','Dust trails fade behind the van; nobody is following.','A hand-drawn road map turns out to be mostly right.'];text=pick(moments);type='relief'}addRoadLog(text,type);updateUI()}
