   function buyPart(id){if(!paused||!$('marketShade').classList.contains('show'))return;const part=marketStock.find(item=>item.id===id);if(!part||scrap<part.price)return;scrap-=part.price;rig[part.slot]=part;marketStock=marketStock.filter(item=>item.id!==id);$('logText').textContent=`${part.name} installed in ${part.slot}. ${Math.floor(scrap)} scrap remaining.`;showToast(`${part.name.toUpperCase()} EQUIPPED / ${part.slot.toUpperCase()}`);updateUI();refreshMarket()}

