172:  function crewState(member){return member.health<=0?'dead':member.health<=35?'critical':member.health<75?'wounded':'fit'}
173:   function choiceDisposition(choice,member){if(choice.trait&&member[`${choice.kind}Trait`]===choice.trait)return 'approve';const text=choice.text.toLowerCase(),food=choice.delta.food||0,scrapGain=(choice.delta.scrap||0)>0,hullRisk=(choice.delta.health||0)<0,hullRepair=(choice.delta.health||0)>0;let score=0;const vote=(yes,no)=>{if(yes)score++;if(no)score--};if(member.positiveTrait==='Tinkerer')vote(hullRepair||scrapGain,hullRisk);if(member.positiveTrait==='Medic')vote(food>0||hullRepair,hullRisk);if(member.positiveTrait==='Scavenger')vote(scrapGain,hullRisk&&!scrapGain);if(member.positiveTrait==='Sharpshooter')vote(/shoot|fire|ambush/.test(text),/long way|stay quiet/.test(text));if(member.negativeTrait==='Paranoid')vote(/open fire|keep rolling|kill the engine|stay quiet/.test(text),/follow the signal|climb the relay|trade a ration/.test(text));if(member.negativeTrait==='Glutton')vote(food>0,food<0);if(member.negativeTrait==='Reckless')vote(/punch|floor it|strip|shoot|keep rolling/.test(text),/long way|stay quiet|kill the engine/.test(text));if(member.negativeTrait==='Sickly')vote(food>0||hullRepair,hullRisk||/climb|punch through/.test(text));return score>0?'approve':score<0?'disapprove':null}
174:   function applyStress(member,amount){if(member.health<=0)return null;member.stress=Math.max(0,Math.min(100,member.stress+amount));if(member.stress<100)return null;member.stress=45;member.health=Math.max(0,member.health-20);const damage=applyHullDamage(8);return `${member.name} MELTDOWN: −20 VITALS, −${Number(damage.toFixed(1))} HULL`;}
175:   function skillName(member){return ({Tinkerer:'REPAIR HULL',Medic:'HEAL CREW',Scavenger:'SALVAGE CACHE',Sharpshooter:'CLEAR AMBUSH'})[member.positiveTrait]}
176:   function canUseSkill(member){if(member.health<=0||member.skillUses<=0||ended||(paused&&!camping))return false;if(member.positiveTrait==='Tinkerer')return health<100;if(member.positiveTrait==='Medic')return crew.some(person=>person.health>0&&person.health<100);return true}
177:   function activateSkill(member){if(!canUseSkill(member))return;member.skillUses--;let message='';if(member.positiveTrait==='Tinkerer'){health=Math.min(100,health+20);message=`${member.name} repaired the hull (+20).`}else if(member.positiveTrait==='Medic'){const target=crew.filter(person=>person.health>0&&person.health<100).sort((a,b)=>a.health-b.health)[0];if(!target){member.skillUses++;return}target.health=Math.min(100,target.health+30);message=`${member.name} treated ${target.name} (+30 vitals).`}else if(member.positiveTrait==='Scavenger'){addScrap(14);message=`${member.name} salvaged a cache (+${Math.round(14*scrapMultiplier())} scrap).`}else{nextEvent+=12;message=`${member.name} cleared the road ahead. Next encounter delayed.`}$('logText').textContent=message;showToast(message);updateUI()}
178:   function updateCrew(){let active=0;$('crewList').innerHTML=crew.map(member=>{const state=crewState(member);if(state!=='dead')active++;const label=state==='dead'?'DOWN':state==='fit'?'FIT':state==='wounded'?'WOUNDED':'CRITICAL';return `<div class="crew-member ${state} ${member.stress>=85?'overstressed':member.stress>=60?'stressed':''}" aria-label="${member.name}, ${label}, ${Math.round(member.health)} percent, ${Math.round(member.stress)} percent stress, ${member.positiveTrait}, ${member.negativeTrait}"><div class="crew-avatar">${member.initial}</div><div class="crew-info"><div class="crew-top"><span class="crew-name">${member.name}</span><span class="crew-status">${label}</span></div><div class="trait-tags"><span class="trait-tag positive">${member.positiveTrait}</span><span class="trait-tag negative">${member.negativeTrait}</span></div><div class="crew-bar"><span style="width:${Math.max(0,member.health)}%"></span></div><div class="stress-row"><span>STRESS</span><strong>${Math.round(member.stress)}%</strong></div><div class="stress-bar"><span style="width:${Math.max(0,member.stress)}%"></span></div><button class="crew-skill" type="button" ${canUseSkill(member)?'':'disabled'}><span>${skillName(member)}</span><small>${member.skillUses}/2 USES</small></button></div></div>`}).join('');$('crewList').querySelectorAll('.crew-skill').forEach((button,index)=>button.onclick=()=>activateSkill(crew[index]));$('crewCount').textContent=`${active} / 3 ACTIVE`}
179:   function renderRig(){const slots=Object.entries(rig);$('rigSlots').innerHTML=slots.map(([slot,part])=>`<div class="rig-slot ${part?'equipped':''}"><span>${slot.toUpperCase()}</span><strong>${part?part.name:'EMPTY'}</strong>${part?`<small>${part.short}</small>`:''}</div>`).join('')}
180:    function updateUI(){for(const [key,val] of [['fuel',fuel],['food',food],['health',health]]){$(key+'Val').textContent=Math.max(0,Math.round(val))+'%';$(key+'Bar').style.width=Math.max(0,val)+'%';} $('distance').textContent=dist.toFixed(1).padStart(4,'0');$('sectorHeader').textContent=`SECTOR 0${sectorIndexAt(dist)+1}`;$('progress').style.width=Math.min(100,dist/5)+'%';$('scrapVal').textContent=Math.floor(scrap);$('moraleVal').textContent=Math.round(morale);$('logTime').textContent=`DAY ${String(1+Math.floor(elapsed/55)).padStart(2,'0')}`;$('scavengeLaunch').disabled=paused||ended||food<5;$('campButton').disabled=ended||(paused&&!camping)||(!camping&&food<15);$('campButton').innerHTML=camping?'<span>▶ &nbsp; RESUME DRIVE</span><small>LEAVE CAMP AND CONTINUE</small>':'<span>⌂ &nbsp; MAKE CAMP</span><small>PAUSE · 15 RATIONS · RESTORE SKILLS</small>';updateCrew();renderRig()}
