const fs = require('node:fs');
const source = fs.readFileSync('index.html', 'utf8');
const match = source.match(/function applyStress\(member,amount\)\{[^}]+\}/);
if (!match) throw new Error('applyStress not found');
let hullDamage = 0;
const applyStress = new Function('applyHullDamage', `${match[0]}; return applyStress;`)(amount => { hullDamage += amount; return amount; });
const member = { name: 'Test Crew', health: 100, stress: 95 };
const note = applyStress(member, 10);
if (member.stress !== 45 || member.health !== 80 || hullDamage !== 8 || !note.includes('MELTDOWN')) throw new Error('Meltdown behavior failed');
const sectors = [...source.matchAll(/name:'(OLIVE-AMBER|RUST-ORANGE|TOXIC-GREEN|ASH-GRAY|NEON-PURPLE)'/g)].map(match => match[1]);
if (sectors.length !== 5) throw new Error(`Expected five scenery palettes; found ${sectors.length}`);
if (!source.includes('dist>=500') || !source.includes('nextMarket=50')) throw new Error('Journey or market milestone missing');
console.log('Meltdown unit check passed; five scenery palettes and 500-mile/50-mile milestones present.');
