const fs=require('node:fs');
const src=fs.readFileSync('index.html','utf8');
const fn=src.match(/function choiceDisposition\(choice,member\)\{.*?\n/)[0];
eval(`${fn}; globalThis.disposition=choiceDisposition`);
const traits=['Pragmatic','Pacifist','Stoic','Greed-Driven','Tech-Savvy'];
const choices=[
 {text:'Trade a ration for fuel',delta:{fuel:18,food:-13}},
 {text:'Strip the bike for rare alloys',delta:{scrap:12,health:-14}},
 {text:'Keep rolling. No stops.',delta:{health:-8}},
 {text:'Take the long way around',delta:{fuel:-15}},
 {text:'Kill the engine and stay quiet',delta:{food:-10,health:-6}},
 {text:'Climb the relay tower',delta:{food:16,health:-12}},
 {text:'Loot the sealed tool locker',delta:{scrap:16,health:-20}},
 {text:'Give them a little fuel',delta:{fuel:-15,food:22}},
 {text:'Barter spare parts for a patch',delta:{health:17,fuel:-10}},
 {text:'Burn fuel. Keep the lights on.',delta:{fuel:-16,health:9}},
];
let failed=false;
for(const trait of traits){
 const outcomes=choices.map(choice=>disposition(choice,{positiveTrait:'Medic',negativeTrait:trait}));
 const approve=outcomes.filter(x=>x==='approve').length,disapprove=outcomes.filter(x=>x==='disapprove').length;
 console.log(`${trait}: ${approve} approve, ${disapprove} disapprove, ${outcomes.filter(x=>!x).length} neutral`);
 if(!approve||!disapprove)failed=true;
}
if(failed)process.exit(1);
