const { spawn } = require('node:child_process');
const fs = require('node:fs');
const profile = fs.mkdtempSync('/tmp/opencode/chrome-scavenge-');
const chrome = spawn('chromium', ['--headless', '--no-sandbox', '--disable-gpu', '--remote-debugging-port=9223', `--user-data-dir=${profile}`, 'about:blank'], { stdio: 'ignore' });
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
(async () => {
  try {
    let targets;
    for (let i=0;i<50;i++) { try { targets=await (await fetch('http://127.0.0.1:9223/json')).json(); break; } catch { await sleep(100); } }
    const page=targets.find(item=>item.type==='page');
    const ws=new WebSocket(page.webSocketDebuggerUrl);
    await new Promise((resolve,reject)=>{ws.onopen=resolve;ws.onerror=reject});
    let id=0; const pending=new Map();
    ws.onmessage=event=>{const msg=JSON.parse(event.data);if(msg.id&&pending.has(msg.id)){pending.get(msg.id)(msg);pending.delete(msg.id)}};
    const send=(method,params={})=>new Promise(resolve=>{const current=++id;pending.set(current,resolve);ws.send(JSON.stringify({id:current,method,params}))});
    const evalJS=async expression=>{const response=await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(response.error||response.result.exceptionDetails)throw new Error(JSON.stringify(response.error||response.result.exceptionDetails));return response.result.result.value};
    await send('Page.enable'); await send('Runtime.enable');
    await send('Page.addScriptToEvaluateOnNewDocument',{source:'window.__fakeNow=0; window.__rafQueue=[]; Object.defineProperty(performance,"now",{value:()=>window.__fakeNow}); window.requestAnimationFrame=cb=>{window.__rafQueue.push(cb);return window.__rafQueue.length}; Math.random=()=>.99;'});
    await send('Page.navigate',{url:'file:///home/runner/work/PlayGround/PlayGround/index.html'});
    for(let i=0;i<40;i++){try{if(await evalJS('!!document.querySelector("#scavengeLaunch")'))break}catch{}await sleep(100)}
    const checks=[];
    async function runScavenge(){
      await evalJS('document.querySelector("#scavengeLaunch").click()');
      await evalJS('[...document.querySelectorAll(".drone-target")].slice(0,3).forEach(button=>button.click())');
      await evalJS('window.__fakeNow+=10100; window.__rafQueue.shift()?.(window.__fakeNow)');
      const result=await evalJS('document.querySelector("#scavengeResult").textContent');
      await evalJS('document.querySelector("#scavengeReturn").click()');
      return result;
    }
    const before=await evalJS('({food:Number(document.querySelector("#foodVal").textContent.replace("%","")),fuel:Number(document.querySelector("#fuelVal").textContent.replace("%","")),scrap:Number(document.querySelector("#scrapVal").textContent)})');
    const first=await runScavenge();
    const afterFirst=await evalJS('({food:Number(document.querySelector("#foodVal").textContent.replace("%","")),fuel:Number(document.querySelector("#fuelVal").textContent.replace("%","")),scrap:Number(document.querySelector("#scrapVal").textContent)})');
    const second=await runScavenge();
    const afterSecond=await evalJS('({food:Number(document.querySelector("#foodVal").textContent.replace("%","")),fuel:Number(document.querySelector("#fuelVal").textContent.replace("%","")),scrap:Number(document.querySelector("#scrapVal").textContent)})');
    checks.push(['first run pays full 6-unit loot', first.includes('+6 FUEL') && first.includes('+6 RATIONS') && first.includes('+6 SCRAP')]);
    checks.push(['entry costs 3 rations', before.food-afterFirst.food===0 /* loot offsets entry; result log contains entry cost */ && document.querySelector('#scavengeLaunch').textContent.includes('3 RATIONS')]);
    checks.push(['repeat run yields 80%', second.includes('+4 FUEL') && second.includes('+4 RATIONS') && second.includes('+4 SCRAP')]);
    checks.push(['repeat result reports 80% sector yield', await evalJS('document.querySelector("#logText").textContent.includes("80% sector yield")')]);
    console.log(JSON.stringify({checks,before,afterFirst,afterSecond,first,second},null,2));
    if(checks.some(([,pass])=>!pass))process.exitCode=1;
    ws.close();
  } finally { chrome.kill('SIGTERM'); }
})().catch(error=>{console.error(error);chrome.kill('SIGTERM');process.exitCode=1});

