function supplyTarget(item){return item.resource==='crew'?crew.filter(member=>member.health>0&&member.health<100).sort((a,b)=>a.health-b.health)[0]:null}
function canBuySupply(item){return scrap>=item.price&&(item.resource==='fuel'?fuel<100:item.resource==='food'?food<100:!!supplyTarget(item))}
function refreshMarket(){$('marketScrap').textContent=Math.floor(scrap);$('marketSupplies').innerHTML=supplyStock.map(item=>{const injured=supplyTarget(item),effect=item.resource==='crew'?`+${item.amount}% CREW HEALTH${injured?` / ${injured.name.toUpperCase()}`:' / NO INJURED CREW'}`:`+${item.amount}% ${item.resource==='fuel'?'FUEL':'RATIONS'}`;return `<button class="market-trade" type="button" data-supply="${item.id}" ${canBuySupply(item)?'':'disabled'}><span>${item.name.toUpperCase()} · ${item.category}<small>${effect}</small></span><strong>${item.price} SCRAP</strong></button>`}).join('');$('marketSupplies').querySelectorAll('[data-supply]').forEach(button=>button.onclick=()=>buySupply(button.dataset.supply));$('marketParts').innerHTML=marketStock.map(part=>`<button class="market-trade part" type="button" data-part="${part.id}" ${scrap<part.price?'disabled':''}><span>${part.name} · ${part.slot}<small>${part.effect}</small></span><strong>${part.price} SCRAP</strong></button>`).join('');$('marketParts').querySelectorAll('[data-part]').forEach(button=>button.onclick=()=>buyPart(button.dataset.part));}

