function setDroneTarget(target){const roll=Math.random(),type=roll<.06?'ammo-cell':roll<.36?'animal':roll<.61?'gasmask':'robot',details={robot:['🤖','Shoot robot for Scrap'],animal:['🐺','Hunt animal for Rations'],gasmask:['😷','Raid gas-mask cache for Fuel and Scrap'],'ammo-cell':['🔋','Collect rare Blaster Ammo Cell']}[type];target.className=`drone-target ${type}`;target.dataset.targetType=type;target.setAttribute('aria-label',details[1]);target.querySelector('.drone-core').textContent=details[0]}
function scaledScavengeLoot(){return Object.fromEntries(Object.entries(scavengeLoot).map(([key,value])=>[key,key==='ammo'?value:Math.round(value*scavengeLootMultiplier)]))}
