function showCampNoise(){paused=true;$('eventKicker').textContent='NIGHT WATCH / CAMP DISTURBANCE';$('eventTitle').textContent='SOMETHING IN THE DARK';$('eventDesc').textContent='A sharp noise snaps the crew awake. You investigate and find a small loss—but no clear sign of what made it.';$('crewEvent').classList.remove('show');$('choices').innerHTML='';const options=[{text:'Check the torn supply bag',summary:'−4 RATIONS',loss:()=>{const n=Math.min(4,food);food-=n;return `−${n} RATIONS`}},{text:'Inspect the fresh claw marks',summary:'−3 HULL',loss:()=>{const n=applyHullDamage(3);return `−${Number(n.toFixed(1))} HULL`}},{text:'Gather the scattered coins',summary:'−4 SCRAP',loss:()=>{const n=Math.min(4,scrap);scrap-=n;return `−${n} SCRAP`}},{text:'Check the exposed gas cap',summary:'−4 FUEL',loss:()=>{const n=Math.min(4,fuel);fuel-=n;return `−${n} FUEL`}}];options.forEach((option,i)=>{const b=document.createElement('button');b.className='choice';b.innerHTML=`<span><span class="key">[${i+1}]</span>${option.text}</span><span class="delta negative">${option.summary}</span>`;b.onclick=()=>resolveCampNoise(option);$('choices').append(b)});$('eventTip').textContent='THE DAMAGE IS MINOR, BUT THE DARKNESS FEELS CROWDED.';$('eventShade').classList.add('show');$('status').innerHTML='⌂&nbsp; NIGHT WATCH';document.querySelectorAll('.scene-wrap').forEach(el=>el.style.filter='saturate(.6)')}
function resolveCampNoise(option){if(!camping||!$('eventShade').classList.contains('show'))return;const loss=option.loss();$('eventShade').classList.remove('show');$('logText').textContent=`Night disturbance investigated. ${loss}. The crew settles back into camp.`;showToast(`NIGHT WATCH / ${loss}`);if(campChainRaid){campPending='roar';campPendingAt=campElapsed+rand(3,5)}else{campPending='';campNextAt=campElapsed+rand(20,32)}campChainRaid=false;$('status').innerHTML='⌂&nbsp; CAMPED';document.querySelectorAll('.scene-wrap').forEach(el=>el.style.filter='saturate(.6)');updateUI();checkEnd()}
function updateCamp(dt){if(!camping||ended||$('eventShade').classList.contains('show'))return;campElapsed+=dt;food=Math.max(0,food-dt*.36*rationUseMultiplier());crew.forEach(member=>{if(member.health>0)member.health=Math.min(100,member.health+dt*.12)});if(campPending&&campElapsed>=campPendingAt){if(campPending==='noise'){campPending='';campChainRaid=Math.random()<.2;showCampNoise()}else if(campPending==='roar'){campPending='raid';campPendingAt=campElapsed+rand(3,5);$('logText').textContent='A distant roar of motorcycles rolls across the dark. Headlights are moving toward the camp.';showToast('DISTANT MOTORCYCLE ROAR / RIDERS APPROACHING...')}else if(campPending==='raid'){campPending='';raidFromCamp=true;showRaid()}}else if(!campPending&&campElapsed>=campNextAt){campPending='noise';campPendingAt=campElapsed+rand(3,5);campChainRaid=false;$('logText').textContent='Something stalks in the shadows...';showToast('SOMETHING STALKS IN THE SHADOWS...')}if(food<=0)checkEnd()}
function toggleCamp(){if($('eventShade').classList.contains('show'))return;if(camping){camping=false;paused=false;campPending='';raidFromCamp=false;$('status').innerHTML='▶&nbsp; EN ROUTE';document.querySelector('.scene-wrap').style.filter='';$('logText').textContent='Camp broken. The van is back on the road.';updateUI();return}if(paused||ended)return;if(food<18){showToast('NOT ENOUGH RATIONS / NEED 18 TO CAMP');return}camping=true;paused=true;food-=18;campElapsed=0;campNextAt=rand(16,24);campPending='';campChainRaid=false;const rested=[];let stressRecovered=0;crew.forEach(member=>{member.skillUses=1;if(member.health>0&&member.stress>0){const recovered=Math.min(30,member.stress);member.stress-=recovered;stressRecovered+=recovered;rested.push(`${member.initial} −${recovered} STRESS`)}});$('status').innerHTML='⌂&nbsp; CAMPED';document.querySelector('.scene-wrap').style.filter='saturate(.6)';$('logText').textContent=`Camp set. Crew skills restored${rested.length?'; stress eased: '+rested.join(', '):''}. Something stalks in the shadows...`;showToast(`CAMP MADE / −18 RATIONS / SOMETHING STALKS IN THE SHADOWS...${stressRecovered?` / −${stressRecovered} STRESS`:''}`);campPending='noise';campPendingAt=campElapsed+rand(3,5);updateUI()}

